109	export function getPlanTier(planName: string): PlanTier {
110	  if (planName === PLAN_STARTER_MONTHLY || planName === PLAN_STARTER_ANNUAL)
111	    return "starter";
112	  if (planName === PLAN_PRO_MONTHLY || planName === PLAN_PRO_ANNUAL)
113	    return "pro";
114	  if (planName === PLAN_ULTIMATE_MONTHLY || planName === PLAN_ULTIMATE_ANNUAL)
115	    return "ultimate";
116	  return "free";
117	}
