153	        data.successColor = "#008060";
154	        data.errorColor = "#D72C0D";
155	        data.backgroundColor = "#FFFFFF";
156	        data.textColor = "#202223";
157	        data.position = "inline";
158	      }
159	      if (!limits.showEtaCodReturn) {
160	        data.showEta = false;
161	        data.showZone = false;
162	        data.showCod = false;
163	        data.showReturnPolicy = false;
164	        data.showCutoffTime = false;
165	        data.showDeliveryDays = false;
166	        data.showDeliveryDate = false;
167	        data.showCountdown = false;
