305	// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
306	function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
307	  if (!rawCss) return "";
308	  // Sanitize the same way the public API does (mirrors api.widget-config.tsx)
309	  const css = rawCss
310	    .replace(/<style\b[^>]*>/gi, "")
311	    .replace(/<\/style>/gi, "")
312	    .replace(/@import\b[^;]*(;|$)/gi, "")
313	    .replace(/\bexpression\s*\(/gi, "")
314	    .replace(/url\s*\(\s*['"]?\s*javascript\s*:/gi, "url(")
315	    .replace(/url\s*\(\s*['"]?\s*data\s*:/gi, "url(");
316	  let result = "";
317	  let remaining = css;
318	  while (remaining.length > 0) {
319	    const openBrace = remaining.indexOf("{");
320	    if (openBrace === -1) break;
321	    const closeBrace = remaining.indexOf("}", openBrace);
322	    if (closeBrace === -1) break;
323	    const selector = remaining.substring(0, openBrace).trim();
324	    const body = remaining.substring(openBrace + 1, closeBrace);
325	    remaining = remaining.substring(closeBrace + 1);
326	    if (selector.startsWith("@")) {
327	      result += selector + "{" + body + "}";
328	    } else if (selector) {
329	      const prefixed = selector.split(",").map(s => {
330	        s = s.trim();
331	        return s ? "#" + wid + " " + s : "";
332	      }).filter(Boolean).join(", ");
333	      result += prefixed + " {" + body + "}";
334	    }
335	  }
336	  return result;
337	}
